const rupee = n => n ? "\u20B9" + Number(n).toLocaleString("en-IN") : "—";

function calcMaterials(qty, dcManual, fsManual, fireRated, dims, scope) {
  const { main, staircase, bedroom, bathroom, duct } = qty;
  const inclDoors  = scope !== "frames";
  const inclFrames = scope !== "doors";
  const total      = main + staircase + bedroom + bathroom + duct;
  const fireDoors  =
    (fireRated?.main      ? main      : 0) +
    (fireRated?.staircase ? staircase : 0) +
    (fireRated?.duct      ? duct      : 0);
  const stdDoors = total - fireDoors;
  const hingesRaw = main*4 + staircase*4 + bedroom*3 + bathroom*3 + duct*4;
  const dcQty = dcManual !== null ? dcManual : fireDoors;

  // Smoke seal: IS 3614 fire doors use perimeter formula (mandatory)
  // IS 5509 fire doors: optional, default 0 unless manually set
  const FIRE_DOOR_KEYS = [
    { key:"main",      qty:main,      frd:60  },
    { key:"staircase", qty:staircase, frd:120 },
    { key:"duct",      qty:duct,      frd:120 },
  ];
  let is3614SealMetres = 0;
  let is3614Count = 0;
  let is5509Count = 0;
  for (const { key, qty: q, frd } of FIRE_DOOR_KEYS) {
    if (!q) continue;
    const std = dims?.[key]?.standard || "IS 3614";
    const w = Number(dims?.[key]?.w) || 0;
    const h = Number(dims?.[key]?.h) || 0;
    if (std === "IS 3614") {
      is3614SealMetres += q * (2 * w + 2 * h) / 1000;
      is3614Count += q;
    } else {
      is5509Count += q;
    }
  }
  // If no door dims entered yet, fall back to door count estimate for IS 3614
  if (is3614Count > 0 && is3614SealMetres === 0) is3614SealMetres = is3614Count * 5.5;
  const fsAutoQty  = fsManual !== null ? fsManual : is3614SealMetres;
  const fsIs3614Mandatory = is3614Count > 0;

  const mats = {
    frames:      { qty: inclFrames ? total : 0,            waste:WASTE.frames,     unit:"Sets",   basis:"1 frame set per door opening" },
    hinges:      { qty: inclDoors  ? hingesRaw : 0,        waste:WASTE.hinges,     unit:"Pairs",  basis:"Doors × hinges per door" },
    anchors:     { qty: inclFrames ? total*6 : 0,          waste:WASTE.anchors,    unit:"Pcs",    basis:"Frames × 6 fixings each (+10%)" },
    lockBody:    { qty: inclDoors  ? main+bedroom+bathroom : 0, waste:WASTE.lockBody, unit:"Pcs", basis:"Main, Bedroom & Bathroom doors" },
    doorClosers: { qty:dcQty,                              waste:WASTE.doorClosers, unit:"Pcs",   basis:dcManual!==null?"Manual override":"1 per fire-rated door", manual:dcManual!==null },
    latchSets:   { qty: inclDoors  ? total : 0,            waste:WASTE.latchSets,  unit:"Units",  basis:"1 per door (spring bolt + strike plate)" },
    handles:     { qty: inclDoors  ? main+bedroom+bathroom : 0, waste:WASTE.handles, unit:"Pairs", basis:"Main, Bedroom & Bathroom doors" },
    fireSeal:    { qty:fsAutoQty,  waste:WASTE.fireSeal,   unit:"Metres",
                   basis: fsManual!==null ? "Manual override"
                        : fsIs3614Mandatory ? `IS 3614: 2×H+2×W per door (${is3614SealMetres.toFixed(1)}m)${is5509Count>0?" · IS 5509: optional (add manually)":""}`
                        : "IS 5509 doors only — smoke seal optional",
                   manual:fsManual!==null, mandatory:fsIs3614Mandatory },
    screws:      { qty: inclFrames ? Math.ceil(total/5) : 0, waste:WASTE.screws,   unit:"Packs",  basis:"ROUNDUP(total ÷ 5) + 10% waste" },
    laminate:    { qty: inclDoors  ? total*2 : 0,          waste:WASTE.laminate,   unit:"Sheets", basis:"2 sheets per door" },
  };
  for (const k in mats) mats[k].orderQty = Math.ceil(mats[k].qty * (1 + mats[k].waste));
  return { mats, total, fireDoors, stdDoors, is3614Count, is5509Count, fsIs3614Mandatory };
}

